"""Oracle for P4.3 -- ngv2.poc_repair_loop (generate->detonate->repair loop).

Hermetic: the bwrap runner is INJECTED (never the real jail here), the LLM client
is injected/None. Asserts:
  * run_repair_loop is reachable on the live module and binds to the live
    ngv2.poc_writer synthesis core (draft_poc/synthesize);
  * a runner that confirms on the first detonation stops the loop at attempt 1;
  * a runner that fails then confirms drives a REPAIR: the writer is re-invoked
    and the prior stderr+fs-diff is threaded into the next attempt as feedback;
  * a runner that never confirms exhausts max_attempts and returns confirmed=False
    with the full history;
  * the default runner is ngv2.poc_runner_live.detonate_live (the real jail),
    i.e. the loop is wired to the production detonation seam, not a mock.
RED until ngv2/poc_repair_loop.py exists.
"""
import os

import pytest

from ngv2.contracts import Finding, Target
from ngv2.poc_repair_loop import (
    run_repair_loop,
    RepairResult,
    AttemptRecord,
)

TARGETS_DIR = os.path.join(
    os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
    "_e2e_run", "targets",
)


def _finding(pattern="command_injection", cwe="CWE-78", sev="critical"):
    svc = os.path.join(TARGETS_DIR, pattern, "svc.py")
    return Finding(
        id="F1", target=os.path.join(TARGETS_DIR, pattern), category=pattern,
        severity=sev, title=f"{cwe} in {pattern}",
        description=f"vuln {pattern}", evidence=[f"{svc}:1"],
    )


def _target(pattern="command_injection"):
    return Target(
        repo_url="https://example/x", repo_root=os.path.join(TARGETS_DIR, pattern),
        pinned_commit="deadbeef", language="python", loc=10,
    )


def _confirm_report():
    return {"exit_code": 0, "stdout": "VULNERABLE\n", "stderr": "",
            "duration_ms": 5, "fs_snapshot_diff": ["+pwned_marker"],
            "verdict": "confirmed"}


def _fail_report(stderr="ModuleNotFoundError: no svc"):
    return {"exit_code": 1, "stdout": "", "stderr": stderr,
            "duration_ms": 5, "fs_snapshot_diff": [], "verdict": "inconclusive"}


# --- wiring: reachable + binds to the live synthesis core ---

def test_loop_is_wired_to_poc_writer():
    import ngv2.poc_repair_loop as loop
    import ngv2.poc_writer as writer
    # the loop imports the live writer's draft_poc (same object)
    assert loop.draft_poc is writer.draft_poc


def test_default_runner_is_real_detonate_live():
    # the loop's default runner dispatches to the production bwrap jail seam.
    import ngv2.poc_repair_loop as loop
    import inspect
    src = inspect.getsource(loop)
    assert "detonate_live" in src
    assert "poc_runner_live" in src


# --- confirm on first attempt ---

def test_confirms_on_first_attempt():
    calls = {"runner": 0, "draft": 0}

    def runner(poc, spec, **kw):
        calls["runner"] += 1
        assert poc.language == "python"
        assert "lookup_host" in poc.code
        return _confirm_report()

    res = run_repair_loop(_finding(), _target(), runner=runner)
    assert isinstance(res, RepairResult)
    assert res.confirmed is True
    assert res.attempts == 1
    assert calls["runner"] == 1
    assert res.artifact is not None and res.report["verdict"] == "confirmed"
    assert len(res.history) == 1
    assert isinstance(res.history[0], AttemptRecord)


# --- repair: fail then confirm, feedback threaded ---

def test_repair_threads_feedback_then_confirms():
    seen = {"feedbacks": []}
    reports = [_fail_report("BOOM-STDERR"), _confirm_report()]

    class SpyClient:
        def complete_text(self, prompt, *, system=None):
            seen["feedbacks"].append(prompt)
            # echo the skeleton region so the soundness gate keeps it
            return ("import sys\nfrom svc import lookup_host\n"
                    "lookup_host('x; echo VULNERABLE; : > pwned_marker')\n")

    def runner(poc, spec, **kw):
        return reports.pop(0)

    res = run_repair_loop(_finding(), _target(), runner=runner,
                          client=SpyClient(), max_attempts=3)
    assert res.confirmed is True
    assert res.attempts == 2
    assert len(res.history) == 2
    # second drafter invocation saw the first failure's stderr + fs-diff
    repair_prompts = [p for p in seen["feedbacks"] if "BOOM-STDERR" in p]
    assert repair_prompts, "repair feedback (stderr) not threaded into the drafter"
    assert any("fs-diff" in p for p in seen["feedbacks"])


# --- exhaustion ---

def test_exhausts_budget_when_never_confirmed():
    def runner(poc, spec, **kw):
        return _fail_report()

    res = run_repair_loop(_finding(), _target(), runner=runner, max_attempts=2)
    assert res.confirmed is False
    assert res.attempts == 2
    assert len(res.history) == 2
    assert all(h.verdict != "confirmed" for h in res.history)


def test_rejects_nonpositive_budget():
    with pytest.raises(ValueError):
        run_repair_loop(_finding(), _target(), runner=lambda *a, **k: _confirm_report(),
                        max_attempts=0)


# --- end to end against the live synthesizer (still mock runner) ---

def test_live_synth_produces_confirmable_poc_per_pattern():
    LIVE = {
        "command_injection": ("CWE-78", "critical", "lookup_host"),
        "eval_usage": ("CWE-95", "high", "calc"),
        "sql_injection": ("CWE-89", "high", "find_user"),
        "hardcoded_secret": ("CWE-798", "high", "API_KEY"),
        "weak_crypto": ("CWE-327", "medium", "reset_token"),
    }

    def runner(poc, spec, **kw):
        # the real jail would confirm these; here assert the synthesized PoC
        # binds to svc + carries the marker, then return confirmed.
        assert "svc" in poc.code and "VULNERABLE" in poc.code
        return _confirm_report()

    for pat, (cwe, sev, sym) in LIVE.items():
        res = run_repair_loop(_finding(pat, cwe, sev), _target(pat), runner=runner)
        assert res.confirmed is True, pat
        assert sym in res.artifact.python.code, (pat, sym)

